import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int L = sc.nextInt();
        int C = sc.nextInt();
        String[] map = new String[L];

        for (int i = 0; i < L; i++) {
            map[i] = sc.next();
        }

        int sr = -1, scCol = -1;
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                if (map[i].charAt(j) == 'o') {
                    sr = i;
                    scCol = j;
                    break;
                }
            }
            if (sr != -1) break;
        }

        boolean[][] visited = new boolean[L][C];
        int[] qr = new int[L * C];
        int[] qc = new int[L * C];

        int head = 0, tail = 0;
        qr[tail] = sr;
        qc[tail] = scCol;
        tail++;
        visited[sr][scCol] = true;

        int lastR = sr, lastC = scCol;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (head < tail) {
            int r = qr[head];
            int c = qc[head];
            head++;

            lastR = r;
            lastC = c;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < L && nc >= 0 && nc < C &&
                    !visited[nr][nc] && map[nr].charAt(nc) != '.') {
                    visited[nr][nc] = true;
                    qr[tail] = nr;
                    qc[tail] = nc;
                    tail++;
                }
            }
        }

        System.out.println((lastR + 1) + " " + (lastC + 1));
    }
}
